siginfo_t info = {0};
pid_t tgid = 1000;
int sig_num = SIGUSR1;

/* Custom payload */
info.si_code = SI_QUEUE;
info.si_value.sival_int = 42;

/* Send signal (with info) to the thread group (TGID) */
syscall(SYS_rt_sigqueueinfo,
        tgid,
        sig_num,
        &info);

pid_t tid = 1001;
info.si_value.sival_ptr = (void*)0xABCD;

/* Send signal (with info) to a specific thread (TID) */
syscall(SYS_rt_tgsigqueueinfo,
        tgid,
        tid,
        sig_num,
        &info);
